///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "valueupIndexSub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    if (data === "") {
        $("#mainContents").load("/error.jsp");
    } else {
        $("#mainContents").empty().append(data);
    }
};

/**
 * @method
 * @name fnIdxInfo
 * @description fn Idx Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnIdxInfo = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "searchIdxInfo");
    await scwin.tx_fnIdxInfo_ajaxsubmit();
};

/**
 * @method
 * @name fnIdxInfoCallBack
 * @description fn Idx Info Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnIdxInfoCallBack = function (data) {
    $("#idxInfo").empty().append(data);
};

/**
 * @method
 * @name fnGetIdxChart
 * @description fn Get Idx Chart 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnGetIdxChart = async function () {
    $c.util.getComponent("dma_fnSearchAjaxsubmitReq").set("method", "searchIdxChart");
    await scwin.tx_fnGetIdxChart_ajaxsubmit();
};

/**
 * @method
 * @name fnIdxChartCallBack
 * @description fn Idx Chart Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnIdxChartCallBack = function (data) {
    $("#idxChart").empty().append(data);
};
